1	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
2	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
3	import {delegatingTo} from './wsTestSupport.js';
4	import {logLines, startEngine, askAfterConnect, setupLogger, teardownEngines} from './conversationListTestHelper.js';
5	
6	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
7	
8	beforeEach(() => {
9	  setupLogger();
10	});
11	
12	afterEach(async () => {
13	  await teardownEngines();
14	});
15	
16	describe('listing conversations over the WebSocket protocol', () => {
17	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
18	    const inner = new InMemorySessionStore();
19	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
20	    const summaries: SessionSummary[] = [
21	      {
22	        sessionId: 's2',
23	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
24	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
25	        entryCount: 4,
26	      },
27	    ];
28	    const store: SessionStore = {
29	      ...delegatingTo(inner),
30	      listFor: (userId, options) => {
31	        seen.push({userId, options});
32	        return summaries;
33	      },
34	    };
35	    const url = await startEngine(store, 'u1');
36	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
37	
38	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
39	
40	    expect({seen, frames}).toEqual({
41	      seen: [{userId: 'u1', options: {limit: 10, before}}],
42	      frames: [
43	        {
44	          type: 'session_list',
45	          sessions: [
46	            {
47	              sessionId: 's2',
48	              createdAt: '2026-01-01T00:00:00.000Z',
49	              updatedAt: '2026-01-01T00:02:00.000Z',
50	              entryCount: 4,
51	            },
52	          ],
53	        },
54	      ],
55	    });
56	  });
57	
58	  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
59	    const inner = new InMemorySessionStore();
60	    const withoutList = await startEngine(delegatingTo(inner));
61	    const failingList = await startEngine({
62	      ...delegatingTo(inner),
63	      listFor: () => Promise.reject(new Error('database offline')),
64	    });
65	
66	    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
67	    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});
68	
69	    expect({
70	      unimplemented: unimplemented.frames,
71	      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
72	      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
73	    }).toEqual({
74	      unimplemented: [{type: 'session_list', sessions: []}],
75	      failed: [{type: 'error', code: 'SERVER_ERROR'}],
76	      logged: [
77	        {
78	          level: 'error',
79	          category: 'ws',
80	          message: expect.any(String),
81	          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
82	        },
83	      ],
84	    });
85	  });
86	
87	  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
88	    const inner = new InMemorySessionStore();
89	    let calls = 0;
90	    const store: SessionStore = {
91	      ...delegatingTo(inner),
92	      listFor: () => {
93	        calls += 1;
94	        return [];
95	      },
96	    };
97	    const url = await startEngine(store);
98	    const badFrames = [
99	      {type: 'list_sessions', limit: 'ten'},
100	      {type: 'list_sessions', limit: -1},
101	      {type: 'list_sessions', limit: 1.5},
102	      {type: 'list_sessions', before: 'not-an-object'},
103	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
104	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
105	      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
106	      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
107	    ];
108	
109	    const codes: Array<string | undefined> = [];
110	    for (const bad of badFrames) {
111	      const {frames} = await askAfterConnect(url, bad);
112	      codes.push(frames[0]?.code);
113	    }
114	    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});
115	
116	    expect({codes, accepted, calls}).toEqual({
117	      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
118	      accepted: [{type: 'session_list', sessions: []}],
119	      calls: 1,
120	    });
121	  });
122	});
